describe('Dropdown Close with Escape Key', () => {
  beforeEach(() => {
    cy.visit('/dropdown-menu');
  });

  it('should close dropdown when Escape key is pressed', () => {
    // Open the dropdown menu
    cy.get('[data-testid="dropdown-button"]').click();
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');
    cy.get('[data-testid="dropdown-menu"]').should('contain', 'Option 1');

    // Press Escape key
    cy.get('body').type('{esc}');

    // Verify dropdown is closed
    cy.get('[data-testid="dropdown-menu"]').should('not.exist');
    cy.get('[data-testid="dropdown-menu"]').should('not.be.visible');
  });

  it('should not close dropdown when Escape key is pressed while dropdown is not open', () => {
    // Verify dropdown is initially closed
    cy.get('[data-testid="dropdown-menu"]').should('not.exist');

    // Press Escape key
    cy.get('body').type('{esc}');

    // Verify dropdown remains closed
    cy.get('[data-testid="dropdown-menu"]').should('not.exist');
  });
});
